export type AllergenKey =
  | 'gluten'
  | 'crustaceans'
  | 'eggs'
  | 'fish'
  | 'peanuts'
  | 'soy'
  | 'milk'
  | 'tree_nuts'
  | 'celery'
  | 'mustard'
  | 'sesame'
  | 'lupins'
  | 'sulphites';

export type Micro =
  | 'potassium'
  | 'magnesium'
  | 'calcium'
  | 'iron'
  | 'zinc'
  | 'folate'
  | 'vitamin_a'
  | 'vitamin_c'
  | 'vitamin_d'
  | 'vitamin_e'
  | 'b12'
  | 'omega3'
  | 'selenium'
  | 'iodine'
  | 'sodium'
  | 'vitamin_k'
  | 'vitamin_b6'
  | 'manganese'
  | 'copper'
  | 'phosphorus';

export type MicroDetailKey = Micro;

export interface FoodNutrition {
  kcal: number;
  protein: number; // g
  carbs: number;   // g
  fat: number;    // g
  fiber: number;   // g
  sugar?: number;   // g - zuccheri totali (opzionale)
  // Micronutrients per 100g (estimated values)
  micronutrients?: {
    potassium?: number;       // mg
    magnesium?: number;       // mg
    calcium?: number;         // mg
    iron?: number;            // mg
    zinc?: number;            // mg
    folate?: number;          // µg
    vitamin_a?: number;       // µg RAE
    vitamin_c?: number;       // mg
    vitamin_d?: number;       // µg
    vitamin_e?: number;       // mg
    b12?: number;             // µg
    omega3?: number;          // mg
    selenium?: number;        // µg
    iodine?: number;          // µg
    sodium?: number;          // mg
    vitamin_k?: number;       // µg
    vitamin_b6?: number;      // mg
    manganese?: number;       // mg
    copper?: number;          // mg
    phosphorus?: number;      // mg
  };
}

export interface FodmapGroupDetail {
  level: 'low' | 'medium' | 'high';
  amountGrams?: number;
  thresholdGrams?: number;
  portionDependent: boolean;
  sourceOrNote: string;
}

export type CostCategory = 'low' | 'medium' | 'high';

export interface FoodItem {
  id: string;
  name: string;
  category: 'Carboidrati/Cereali' | 'Proteine/Formaggi' | 'Verdura' | 'Frutta' | 'Condimenti/Altro';
  fodmapLevel: 'low' | 'medium' | 'high';
  triggerGroup?: 'Fruttani' | 'Lattosio' | 'Fruttosio' | 'Galattani' | 'Polioli';
  alternative?: string;
  /** Allergeni presenti nell'alimento (chiavi normalizzate) */
  allergens?: AllergenKey[];
  /** Mesi (1-12) di disponibilità tipica del prodotto fresco in ambito mediterraneo. Omesso = disponibile tutto l'anno (conserve, essiccati, allevamento, importazione continua). */
  months?: number[];
  /** Valori nutrizionali indicativi per 100g di parte edibile */
  nutrition: FoodNutrition;
  /** Oligoelementi/micronutrients di cui l'alimento è fonte rilevante */
  micros?: Micro[];
  /** Dettaglio quantitativo dei micronutrients per 100g */
  microDetails?: Partial<Record<MicroDetailKey, number>>;
  /** Dettagli FODMAP completi per gruppo */
  fodmapDetails?: Partial<Record<'fructans' | 'galactans' | 'lactose' | 'fructose' | 'sorbitol' | 'mannitol', FodmapGroupDetail>>;
  /** Tipi di pasto adatti per questo alimento (determina da quale slot può essere usato) */
  mealSuitability?: 'breakfast' | 'snack' | 'lunch_dinner' | 'any' | ('breakfast' | 'snack' | 'lunch_dinner' | 'any')[];
  /** Profilo di sapore: dolce, salato o neutro */
  flavor?: 'sweet' | 'savory' | 'neutral';
  /** Sottocategoria per matching culinario (es. 'grain', 'protein', 'fat', 'dairy', 'vegetable', 'fruit', 'spice', 'condiment') */
  subCategory?: string;
  /** Categoria di costo per sostenibilità economica */
  costCategory?: CostCategory;
  /** Peso unitario in grammi per alimenti con unità specifiche (es. 50g per uovo, 125g per tofu panetto, 5g per noce) */
  unitWeight?: number;
}

